package main

import (
	"context"
	"fmt"
	"time"

	"github.com/pkg/errors"

	gormadapter "github.com/xolo-gateway/xolo/internal/adapter/gorm"
	"github.com/xolo-gateway/xolo/internal/core/model"
)

// caller describes a recurring consumer of the gateway. The usage history is
// generated by replaying every caller over the requested number of days.
type caller struct {
	label string
	// Exactly one of userID / appID is set, mirroring what the proxy records.
	userID  string
	appID   string
	orgID   string
	tokenID string // empty = web session
	models  []string
	// minReq/maxReq bound the number of daily requests (inclusive).
	minReq, maxReq int
	// promptScale scales the token volume of each request.
	promptScale float64
	// weekdaysOnly skips saturdays and sundays, which makes the usage charts
	// show a realistic weekly rhythm.
	weekdaysOnly bool
}

func callers() []caller {
	return []caller{
		{
			label: "alice", userID: userAlice, orgID: orgAcme, tokenID: "tok-alice-acme",
			models: []string{modelAcmeGPT4o, modelAcmeGPT4oMini}, minReq: 8, maxReq: 25,
			promptScale: 1.4, weekdaysOnly: true,
		},
		{
			label: "bob", userID: userBob, orgID: orgAcme,
			models: []string{modelAcmeGPT4oMini, modelAcmeMistral}, minReq: 4, maxReq: 14,
			promptScale: 1, weekdaysOnly: true,
		},
		{
			label: "carol/acme", userID: userCarol, orgID: orgAcme, tokenID: "tok-carol-acme",
			models: []string{modelAcmeMistral, modelAcmeEmbeddings}, minReq: 10, maxReq: 30,
			promptScale: 0.8, weekdaysOnly: false,
		},
		{
			// Small volumes but a very tight daily quota: the enforcer must reject
			// their next call.
			label: "dave", userID: userDave, orgID: orgAcme,
			models: []string{modelAcmeGPT4oMini}, minReq: 2, maxReq: 6,
			promptScale: 0.6, weekdaysOnly: true,
		},
		{
			label: "ci", appID: appAcmeCI, orgID: orgAcme, tokenID: "tok-app-acme-ci",
			models: []string{modelAcmeGPT4oMini}, minReq: 20, maxReq: 60,
			promptScale: 0.5, weekdaysOnly: false,
		},
		{
			label: "carol/globex", userID: userCarol, orgID: orgGlobex, tokenID: "tok-carol-globex",
			models: []string{modelGlobexSonnet}, minReq: 3, maxReq: 12,
			promptScale: 2, weekdaysOnly: true,
		},
		{
			label: "erin", userID: userErin, orgID: orgGlobex, tokenID: "tok-erin-globex",
			models: []string{modelGlobexSonnet}, minReq: 5, maxReq: 18,
			promptScale: 1.6, weekdaysOnly: true,
		},
	}
}

func (s *seeder) seedUsage(ctx context.Context) error {
	models := map[string]llmModel{}
	for _, m := range seededModels {
		models[m.entity.ID] = m
	}

	providers := map[string]*gormadapter.Provider{}
	var providerRows []*gormadapter.Provider
	if err := s.db.Find(&providerRows).Error; err != nil {
		return errors.WithStack(err)
	}
	for _, p := range providerRows {
		providers[p.ID] = p
	}

	orgs := map[string]*gormadapter.Organization{}
	var orgRows []*gormadapter.Organization
	if err := s.db.Find(&orgRows).Error; err != nil {
		return errors.WithStack(err)
	}
	for _, o := range orgRows {
		orgs[o.ID] = o
	}

	var batch []*gormadapter.UsageRecord
	seq := 0

	for day := s.days - 1; day >= 0; day-- {
		date := now.AddDate(0, 0, -day)

		for _, c := range callers() {
			if c.weekdaysOnly && (date.Weekday() == time.Saturday || date.Weekday() == time.Sunday) {
				continue
			}

			count := c.minReq + s.rand.Intn(c.maxReq-c.minReq+1)
			for i := 0; i < count; i++ {
				modelID := c.models[s.rand.Intn(len(c.models))]
				m := models[modelID]
				provider := providers[m.entity.ProviderID]
				org := orgs[c.orgID]

				prompt, cached, completion := s.tokenCounts(m, c.promptScale)
				providerCost := computeCost(m.entity, prompt, cached, completion)

				cost := providerCost
				currency := provider.Currency
				if org.Currency != currency {
					cost = convert(providerCost, currency, org.Currency)
					currency = org.Currency
				}

				seq++
				record := &gormadapter.UsageRecord{
					ID:                fmt.Sprintf("usg-%06d", seq),
					CreatedAt:         s.requestInstant(date),
					UserID:            c.userID,
					ApplicationID:     c.appID,
					OrgID:             c.orgID,
					ProviderID:        m.entity.ProviderID,
					ModelID:           modelID,
					ProxyModelName:    m.entity.ProxyName,
					ResolvedModelName: org.Slug + "/" + m.entity.ProxyName,
					AuthTokenID:       c.tokenID,
					PromptTokens:      prompt,
					CachedTokens:      cached,
					CompletionTokens:  completion,
					TotalTokens:       prompt + completion,
					Cost:              cost,
					Currency:          currency,
					CostSource:        string(model.CostSourceComputed),
					PlanCovered:       boolToInt(provider.BillingMode == string(model.BillingModeSubscription)),
					ProviderCost:      providerCost,
				}

				batch = append(batch, record)
				s.usageCost[c.orgID] += cost
				s.usageRecords++

				if len(batch) >= 500 {
					if err := s.db.Create(&batch).Error; err != nil {
						return errors.WithStack(err)
					}
					batch = batch[:0]
				}
			}
		}
	}

	if len(batch) > 0 {
		if err := s.db.Create(&batch).Error; err != nil {
			return errors.WithStack(err)
		}
	}

	// The records were written in bulk, not through the store, so the budget
	// counters the quota enforcer reads were never incremented. Rebuilding them
	// here is what makes a seeded instance enforce the quotas its usage history
	// implies.
	return errors.WithStack(gormadapter.RebuildQuotaUsage(s.db))
}

// tokenCounts draws a plausible triple (prompt, cached, completion) for one
// request. Cached tokens are always a subset of the prompt tokens, as reported
// by the providers.
func (s *seeder) tokenCounts(m llmModel, scale float64) (prompt, cached, completion int) {
	prompt = int(float64(400+s.rand.Intn(3600)) * scale)

	// Embedding models never produce completion tokens.
	if m.entity.CapEmbeddings != 0 {
		return prompt, 0, 0
	}

	// Roughly one request out of three benefits from prompt caching.
	if s.rand.Intn(3) == 0 {
		cached = prompt * (30 + s.rand.Intn(50)) / 100
	}

	completion = int(float64(80+s.rand.Intn(1200)) * scale)

	return prompt, cached, completion
}

// requestInstant spreads the requests of a day over office hours.
func (s *seeder) requestInstant(date time.Time) time.Time {
	instant := time.Date(date.Year(), date.Month(), date.Day(), 8, 0, 0, 0, time.UTC).
		Add(time.Duration(s.rand.Intn(10*3600)) * time.Second)

	// Never generate a record in the future: the last day is truncated at `now`.
	if instant.After(now) {
		instant = now.Add(-time.Duration(s.rand.Intn(3600)) * time.Second)
	}

	return instant
}

// computeCost mirrors the formula of the usage tracker hook
// (internal/adapter/proxy/usage_tracker.go), so aggregates displayed by the UI
// stay consistent with what a real request would have recorded.
func computeCost(m *gormadapter.LLMModel, prompt, cached, completion int) int64 {
	cachedCost := m.CachedPromptCostPer1KTokens
	if cachedCost == 0 {
		cachedCost = m.PromptCostPer1KTokens
	}

	nonCached := prompt - cached

	return (int64(nonCached) * m.PromptCostPer1KTokens / 1000) +
		(int64(cached) * cachedCost / 1000) +
		(int64(completion) * m.CompletionCostPer1KTokens / 1000)
}

// convert applies the same frozen rates as the seeded exchange_rates rows.
func convert(amount int64, from, to string) int64 {
	switch {
	case from == to:
		return amount
	case from == "USD" && to == "EUR":
		return int64(float64(amount) * usdToEUR)
	case from == "EUR" && to == "USD":
		return int64(float64(amount) / usdToEUR)
	default:
		return amount
	}
}

func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}
